import { describe, expect, it } from "vitest";
import { roundCents } from "../src/billing/round";

describe("roundCents", () => {
  it("sends exact halves to the even cent so invoices carry no upward bias", () => {
    expect(roundCents(0.5)).toBe(0);
    expect(roundCents(1.5)).toBe(2);
    expect(roundCents(2.5)).toBe(2);
    expect(roundCents(-2.5)).toBe(-2);
    expect(roundCents(-3.5)).toBe(-4);
  });

  it("rounds non-half fractions to the nearest cent", () => {
    expect(roundCents(2.49)).toBe(2);
    expect(roundCents(2.51)).toBe(3);
    expect(roundCents(-2.51)).toBe(-3);
    expect(roundCents(7)).toBe(7);
  });

  it("treats float-error halves from summed line items as halves", () => {
    expect(roundCents(0.1 + 0.2 + 2.2)).toBe(2);
  });
});

